package expo.modules.plugin

import org.gradle.api.Plugin
import org.gradle.api.Project

/**
 * Extension for configuring Expo modules
 */
class ExpoModuleExtension {
    Boolean canBePublished = true
    
    void canBePublished(Boolean value) {
        this.canBePublished = value
    }
}

/**
 * Expo Module Gradle Plugin - Applies common configuration for Expo modules
 */
class ExpoModuleGradlePlugin implements Plugin<Project> {
    @Override
    void apply(Project project) {
        // Create the expoModule extension
        project.extensions.create('expoModule', ExpoModuleExtension)
        
        // Skip if this is an application module (has com.android.application plugin)
        if (project.plugins.hasPlugin('com.android.application')) {
            project.logger.info("expo-module-gradle-plugin: Skipping ${project.name} - is an application module")
            return
        }
        
        // Apply Android Library plugin if not applied and not an application
        if (!project.plugins.hasPlugin('com.android.library')) {
            project.plugins.apply('com.android.library')
        }
        
        // Apply Kotlin Android plugin if not already applied
        if (!project.plugins.hasPlugin('kotlin-android')) {
            project.plugins.apply('kotlin-android')
        }

        // Configure Android defaults IMMEDIATELY (not afterEvaluate)
        def android = project.extensions.findByName('android')
        if (android) {
            // Set SDK versions
            android.compileSdk = getCompileSdkVersion(project)
            android.defaultConfig {
                minSdk = getMinSdkVersion(project)
                targetSdk = getTargetSdkVersion(project)
            }
            
            // Configure Kotlin options
            android.compileOptions {
                sourceCompatibility = org.gradle.api.JavaVersion.VERSION_17
                targetCompatibility = org.gradle.api.JavaVersion.VERSION_17
            }
            
            android.kotlinOptions {
                jvmTarget = "17"
            }
        }

        // Add expo-modules-core as dependency only for library modules
        def coreProject = project.rootProject.findProject(':expo-modules-core')
        if (coreProject != null && project.name != 'expo-modules-core') {
            project.dependencies {
                implementation coreProject
            }
        }
    }
    
    private static int getCompileSdkVersion(Project project) {
        def value = project.rootProject.findProperty('android.compileSdkVersion')
        return value ? Integer.parseInt(value.toString()) : 35
    }
    
    private static int getMinSdkVersion(Project project) {
        def value = project.rootProject.findProperty('android.minSdkVersion')
        return value ? Integer.parseInt(value.toString()) : 24
    }
    
    private static int getTargetSdkVersion(Project project) {
        def value = project.rootProject.findProperty('android.targetSdkVersion')
        return value ? Integer.parseInt(value.toString()) : 34
    }
}

